package com.fasterxml.jackson.core.io;

import com.fasterxml.jackson.core.JsonEncoding;
import com.fasterxml.jackson.core.util.BufferRecycler;
import com.fasterxml.jackson.core.util.TextBuffer;
import java.io.*;
import java.lang.reflect.Constructor;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertThrows;

/**
 * Unit tests for IOContext._verifyRelease.
 * Since _verifyRelease is protected, we use reflection to access it.
 */
public class IOContext__verifyRelease_TriageGen1Test {

    private IOContext ioContext;
    private Method verifyReleaseMethod;

    @Before
    public void setUp() throws Exception {
        // Access the protected constructor
        Constructor<IOContext> constructor = IOContext.class.getDeclaredConstructor(BufferRecycler.class, Object.class, boolean.class);
        constructor.setAccessible(true);
        ioContext = constructor.newInstance(new BufferRecycler(), null, false);

        // Access the protected method _verifyRelease(byte[], byte[])
        verifyReleaseMethod = IOContext.class.getDeclaredMethod("_verifyRelease", byte[].class, byte[].class);
        verifyReleaseMethod.setAccessible(true);
    }

    /**
     * Test case: toRelease == src
     * Result: Should NOT throw exception (identity check)
     */
    @Test
    public void testVerifyRelease_SameBuffer() throws Exception {
        byte[] buffer = new byte[10];
        verifyReleaseMethod.invoke(ioContext, buffer, buffer);
    }

    /**
     * Test case: toRelease != src AND toRelease.length > src.length
     * Result: Should NOT throw exception (buffer is larger or equal size, allowing for shrinking)
     */
    @Test
    public void testVerifyRelease_LargerBuffer() throws Exception {
        byte[] src = new byte[10];
        byte[] toRelease = new byte[11];
        verifyReleaseMethod.invoke(ioContext, toRelease, src);
    }

    /**
     * Test case: toRelease != src AND toRelease.length == src.length
     * Result: Should NOT throw exception (the check is to prevent shrinking, so equal is fine)
     * Note: The logic is (toRelease.length <= src.length), so if length is equal, it throws.
     * Wait, looking at the code: if ((toRelease != src) && (toRelease.length <= src.length)) { throw ... }
     * So if length is equal, it SHOULD throw.
     */
    @Test
    public void testVerifyRelease_EqualLengthThrows() throws Exception {
        byte[] src = new byte[10];
        byte[] toRelease = new byte[10];

        // Since invoke() wraps exceptions in InvocationTargetException
        try {
            verifyReleaseMethod.invoke(ioContext, toRelease, src);
            org.junit.Assert.fail("Expected exception due to equal length and different references");
        } catch (InvocationTargetException e) {
            // The actual exception is the cause
            org.junit.Assert.assertTrue(e.getCause() != null);
        }
    }

    /**
     * Test case: toRelease != src AND toRelease.length < src.length
     * Result: Should throw exception (shrinking detected)
     */
    @Test
    public void testVerifyRelease_SmallerBufferThrows() throws Exception {
        byte[] src = new byte[10];
        byte[] toRelease = new byte[5];

        try {
            verifyReleaseMethod.invoke(ioContext, toRelease, src);
            org.junit.Assert.fail("Expected exception due to smaller length");
        } catch (InvocationTargetException e) {
            // Success: exception was thrown
        }
    }

    /**
     * Test case: toRelease != src AND toRelease.length > src.length
     * Result: Should NOT throw exception
     */
    @Test
    public void testVerifyRelease_DifferentReferenceLargerLength() throws Exception {
        byte[] src = new byte[10];
        byte[] toRelease = new byte[20];
        verifyReleaseMethod.invoke(ioContext, toRelease, src);
    }
}
